// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        address actor = address(0x1234);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();
        bool ok;
        vm.prank(actor);
        try c.withdrawBalance() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
